#include "Plugin.h"
#include <iostream>
void check(bool b,const char* message){if(!b)throw std::runtime_error(message);}
void wait(ChoirProcessor& p){double end=juce::Time::getMillisecondCounterHiRes()+240000;while(p.isBusy()){check(juce::Time::getMillisecondCounterHiRes()<end,"Worker timeout");juce::Thread::sleep(2);}}
double power(const juce::AudioBuffer<float>& audio){double sum=0;for(int ch=0;ch<audio.getNumChannels();++ch)for(int i=0;i<audio.getNumSamples();++i)sum+=audio.getSample(ch,i)*audio.getSample(ch,i);return sum;}
int main(int argc,char** argv){try{using namespace juce;using namespace noori_choir;ScopedJuceInitialiser_GUI init;std::atomic<bool> cancel{false};std::atomic<float> progress{0};
 auto out=argc>1?File(argv[1]):File::getCurrentWorkingDirectory();auto project=out.getChildFile("ChoirTest-"+Uuid().toString());check(project.createDirectory().wasOk(),"Project folder");
 struct Cleanup{File folder;~Cleanup(){folder.deleteRecursively();}} cleanup{project};
 VocalFile fixture;fixture.rate=48000;fixture.name="Original";fixture.sampleOffset=96000;fixture.audio.setSize(1,48000);fixture.audio.clear();for(int i=2400;i<45600;++i)fixture.audio.setSample(0,i,float(.3*std::sin(2*pi*220*i/48000.)));
 auto input=project.getChildFile("Original.wav");writeWave(input,fixture,32,true,cancel);auto decoded=readWav(input,cancel);check(decoded.sampleOffset==96000,"BWF source position round trip");check(decoded.audio.getSample(0,4000)==fixture.audio.getSample(0,4000),"Lossless float32 input");
 ChoirProcessor p(noori_licensing::Config{});p.setRateAndBufferSizeDetails(48000,256);p.prepareToPlay(48000,256);p.importWav(input);wait(p);check(p.hasSource(),"WAV import");p.generate();wait(p);check(p.stemCount()==8,"Eight generated musical singers");check(p.dragFiles().size()==8,"Eight existing drag files prepared");for(auto& path:p.dragFiles())check(File(path).existsAsFile(),"Drag file remains available");
 auto s=p.session();for(int i=0;i<48000;++i)check(s->stems[0].dry->audio.getSample(0,i)==fixture.audio.getSample(0,i),"Generated Main preserves original vocal samples");for(const auto& stem:s->stems){check(stem.dry->audio.getNumSamples()==48000&&stem.wet->audio.getNumSamples()==48000,"Same dry/wet duration");check(power(stem.dry->audio)>.1,"Audible generated singer");for(int i=0;i<2400;++i)check(stem.dry->audio.getSample(0,i)==0,"Original leading silence retained");}
 p.exportTo(project);wait(p);auto exported=p.exportedFiles();check(exported.size()==8,"Eight separate exports");for(auto& file:exported){auto vocal=readWav(File(file),cancel);check(vocal.rate==48000&&vocal.audio.getNumSamples()==48000&&vocal.audio.getNumChannels()==2,"Synchronized stereo PCM24 stems");check(vocal.sampleOffset==96000,"Stem BWF alignment");}
 p.setValue("floatWav",1);p.setValue("printFx",0);p.exportTo(project);wait(p);for(auto& file:p.exportedFiles()){check(!exported.contains(file)&&File(exported[0]).existsAsFile(),"Repeated export never overwrites earlier take");auto vocal=readWav(File(file),cancel);check(vocal.audio.getNumSamples()==48000,"Float32 export duration");}
 // Re-render/export preparation must never stop or rewind the running audition.
 MidiBuffer fxMidi;AudioBuffer<float> fxBlock(2,256);p.play();p.processBlock(fxBlock,fxMidi);const auto positionBeforeFx=p.playhead();
 p.setValue("lowCut",180);p.setValue("reverb",.6f);p.applyFx();check(p.isPlaying(),"FX render does not stop playback immediately");wait(p);check(p.isPlaying()&&p.playhead()==positionBeforeFx,"FX publication preserves running cursor and playback mode");
 p.processBlock(fxBlock,fxMidi);check(p.playhead()>positionBeforeFx,"Playback advances after FX render");
 for(int n=0;n<12;++n){p.setValue("lowCut",float(n*30));p.setValue("brightness",float(n-6));p.setValue("reverb",n/12.f);p.processBlock(fxBlock,fxMidi);for(int ch=0;ch<2;++ch)for(int i=0;i<256;++i)check(std::isfinite(fxBlock.getSample(ch,i)),"Live knob movement stays finite");}p.stop();
 auto old=s->stems[0].wet;p.setValue("lowCut",450);p.setValue("brightness",-8);p.setValue("reverb",0);p.applyFx();wait(p);s=p.session();check(power(s->stems[0].wet->audio)<power(old->audio)*.6,"Post FX changes actual rendered audio");
 MidiBuffer midi;AudioBuffer<float> block(2,256);double energy=0;p.play();for(int i=0;i<200;++i){block.clear();p.processBlock(block,midi);energy+=power(block);}check(energy>.1,"Synchronized choir audition produces audio through processor");p.stop();
 for(int i=0;i<8;++i){auto mix=p.stemMix(i);mix.mute=true;p.setStemMix(i,mix);}p.play();energy=0;for(int i=0;i<200;++i){block.clear();p.processBlock(block,midi);energy+=power(block);}check(energy==0,"Mute controls affect actual preview");
 auto mix=p.stemMix(0);mix.mute=false;mix.solo=true;mix.gain=-9;mix.pan=-.4f;p.setStemMix(0,mix);MemoryBlock state;p.getStateInformation(state);
 ChoirProcessor restored(noori_licensing::Config{});restored.setStateInformation(state.getData(),int(state.getSize()));wait(restored);check(restored.stemCount()==8&&restored.hasSource(),"Persistent source and stems survive project restore");check(restored.stemMix(0).solo&&restored.stemMix(0).gain==-9,"Per-voice mix restored");check(restored.value("lowCut")==450,"FX settings restored");
 p.generate();p.setStateInformation(state.getData(),int(state.getSize()));wait(p);check(p.stemCount()==8&&p.stemMix(0).gain==-9,"State restore safely supersedes a running render");
 p.generate(2);wait(p);check(p.stemCount()==8,"Regenerate one singer retains other voices");p.removeStem(7);wait(p);check(p.stemCount()==7,"Delete singer updates session");p.exportTo(project,-2);wait(p);check(p.exportedFiles().size()==1,"Explicit mix export is separate from stems");
 auto snapshot=p.session();auto before=project.getChildFile("NOORI CHOIR").getNumberOfChildFiles(File::findFiles);cancel=true;bool stopped=false;try{exportSession(*snapshot,project.getChildFile("NOORI CHOIR"),std::vector<StemMix>(7),24,true,true,-1,cancel,progress);}catch(...){stopped=true;}cancel=false;check(stopped&&project.getChildFile("NOORI CHOIR").getNumberOfChildFiles(File::findFiles)==before,"Cancelled export leaves no partial files");
 p.clearSource();p.startCapture();for(int i=0;i<12;++i){for(int ch=0;ch<2;++ch)for(int n=0;n<256;++n)block.setSample(ch,n,float(.2*std::sin((i*256+n)*.03)));p.processBlock(block,midi);}p.stopCapture();wait(p);check(p.hasSource()&&p.session()->source->audio.getNumSamples()==3072,"Track capture has exact sample count");
 // AIFF is decoded using the actual JUCE reader, not treated as a WAV alias.
 AiffAudioFormat aiff;auto aif=project.getChildFile("vocal.aif");auto stream=aif.createOutputStream();std::unique_ptr<AudioFormatWriter> writer(aiff.createWriterFor(stream.get(),44100,1,16,{},0));check(bool(writer),"AIFF writer");stream.release();check(writer->writeFromAudioSampleBuffer(fixture.audio,0,10000),"AIFF fixture");writer.reset();p.importWav(aif);wait(p);check(p.hasSource()&&p.session()->source->rate==44100,"AIFF import");
 check(out.getChildFile("choir-files.ok").replaceWithText("PASS WAV/AIFF, musical stems, synchronized preview, Post FX, BWF/float export, persistent cache, concurrent restore, capture, regenerate and cancellation.\n"),"Test marker");
 std::cout<<"PASS complete choir file and processor workflow\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
